nft_ruleset:
table ip filter {
	chain OUTPUT {
		type filter hook output priority filter; policy drop;
		oifname "lo" counter packets 0 bytes 0 accept
		ct state related,established counter packets 1 bytes 40 accept
		skuid 1003 counter packets 0 bytes 0 log prefix "stopcheck-egress-uid " flags skuid
		skuid != 1003 counter packets 0 bytes 0 log prefix "stopcheck-egress-other " flags skuid
	}
}
table ip6 filter {
	chain OUTPUT {
		type filter hook output priority filter; policy drop;
		oifname "lo" counter packets 0 bytes 0 accept
		ct state related,established counter packets 0 bytes 0 accept
		meta l4proto ipv6-icmp icmpv6 type nd-router-solicit counter packets 0 bytes 0 accept
		meta l4proto ipv6-icmp icmpv6 type nd-neighbor-solicit counter packets 0 bytes 0 accept
		meta l4proto ipv6-icmp icmpv6 type nd-neighbor-advert counter packets 0 bytes 0 accept
		skuid 1003 counter packets 0 bytes 0 log prefix "stopcheck-egress-uid " flags skuid
		skuid != 1003 counter packets 0 bytes 0 log prefix "stopcheck-egress-other " flags skuid
	}
}
